INSERT INTO blog_articles (title, slug, category_id, service_name, excerpt, content, meta_title, meta_description, meta_keywords, featured_image, image_url, status, created_at, updated_at, content_type)
VALUES ('Écrire pour Google quand on est une TPE : la méthode simple', 'ecrire-pour-google-tpe', (SELECT id FROM service_categories WHERE slug = 'seo'), 'SEO', 'Vos pages ne parlent pas comme vos clients ? Trouver leurs mots, une page par sujet, un titre clair et des liens entre pages : la méthode pour être trouvé sur Google.', '<div class="en-bref"> <p class="en-bref-titre">En bref</p> <ul> <li>Google classe les pages qui répondent le mieux à la question posée. Écrire pour Google, c''est d''abord écrire pour vos clients, avec les mots qu''ils tapent.</li> <li>Une page = un sujet = une recherche principale. Le titre, le premier paragraphe et les intertitres doivent la reprendre naturellement.</li> <li>Reliez vos pages entre elles et publiez peu, mais utile : une page par service et par commune vaut mieux que vingt articles copiés.</li> </ul> </div> <p>Vous avez un site, mais personne ne le trouve sur Google. Souvent, le problème n''est pas technique : les pages ne parlent pas comme les clients. Un plombier écrit « Interventions sanitaires », alors que ses clients tapent « plombier Saint-Pierre fuite d''eau ». Google ne fait pas le lien à votre place.</p> <p>La bonne nouvelle, c''est qu''écrire pour Google ne demande ni outil payant ni jargon. Google le dit lui-même dans son guide de démarrage : il cherche le contenu le plus utile pour la personne qui cherche. Voici la méthode, à appliquer page par page.</p> <h2>Trouver les mots de vos clients</h2> <p>Avant d''écrire, notez les recherches que vos clients font vraiment. Trois sources gratuites suffisent :</p> <ul class="checklist"> <li><strong>Vos clients eux-mêmes</strong> : les questions posées au téléphone, par message ou au comptoir. Ce sont vos meilleurs mots-clés.</li> <li><strong>Les suggestions de Google</strong> : tapez le début d''une recherche (« électricien Saint-Denis ») et notez ce que Google propose, ainsi que le bloc « Autres questions posées ».</li> <li><strong>La Search Console</strong>, si votre site y est relié : le rapport « Performances » montre les recherches qui ont déjà affiché votre site. Voir notre <a href="/blog/google-analytics-search-console">pas à pas Search Console</a>.</li> </ul> <p>Rangez ensuite ces recherches par intention : celles qui veulent un prix, celles qui veulent un prestataire près de chez elles, celles qui veulent comprendre avant d''acheter. Chaque intention mérite sa propre page.</p> <h2>Une page, un sujet, une recherche principale</h2> <table class="table-article"> <thead><tr><th>Type de page</th><th>Recherche visée (exemple)</th><th>Ce que la page doit contenir</th></tr></thead> <tbody> <tr><td>Page service</td><td>« pose de climatisation Saint-Paul »</td><td>Ce que vous faites, la zone, les délais, une fourchette de prix, un bouton de contact</td></tr> <tr><td>Page commune ou zone</td><td>« paysagiste Le Tampon »</td><td>Vos réalisations sur place, les communes couvertes, comment vous joindre</td></tr> <tr><td>Article guide</td><td>« comment entretenir une climatisation »</td><td>Une réponse complète et concrète, puis un lien vers la page service</td></tr> <tr><td>Page prix</td><td>« prix ravalement de façade La Réunion »</td><td>Ce qui fait varier le prix, des fourchettes honnêtes, ce qui est inclus</td></tr> </tbody> </table> <p>Deux pages qui visent la même recherche se font concurrence. Mieux vaut une seule page complète que deux pages moyennes.</p> <h2>Écrire la page en 6 étapes</h2> <ol class="etapes"> <li><strong>Le titre de la page (balise title).</strong> Environ 60 caractères, avec la recherche principale au début et votre nom à la fin : « Plombier à Saint-Pierre : dépannage et fuites | Martin Plomberie ».</li> <li><strong>La meta description.</strong> Environ 150 caractères qui donnent envie de cliquer : ce que le client trouvera, et un élément concret (zone, délai, devis gratuit). Google ne l''affiche pas toujours, mais elle aide quand il le fait.</li> <li><strong>Le titre visible (h1) et le premier paragraphe.</strong> Dites tout de suite de quoi parle la page et pour qui. Pas de « Bienvenue sur notre site ».</li> <li><strong>Des intertitres (h2) qui répondent aux questions.</strong> « Combien coûte… », « En combien de temps… », « Dans quelles communes… ». Un lecteur pressé doit comprendre la page en lisant seulement les intertitres.</li> <li><strong>Des preuves concrètes.</strong> Photos de vos réalisations, étapes de votre méthode, ce qui est inclus ou non. C''est ce qui distingue votre page de celle d''un concurrent.</li> <li><strong>Un appel à l''action clair.</strong> Téléphone cliquable, formulaire court ou prise de rendez-vous, visible sans chercher.</li> </ol> <div class="encadre-exemple"> <p class="encadre-titre">Exemple (cas fictif) : une boulangerie à Saint-Joseph</p> <p>Son site n''avait qu''une page d''accueil « Bienvenue chez nous ». La gérante note les questions de ses clients : gâteaux d''anniversaire sur commande, pain sans gluten, horaires du dimanche. Elle crée trois pages, une par sujet, avec des photos de ses gâteaux, les délais de commande et un formulaire. Chaque page renvoie vers les deux autres et vers la fiche Google de la boutique.</p> </div> <h2>Relier les pages entre elles</h2> <p>Les liens internes aident Google à comprendre quelles pages comptent, et aident vos visiteurs à trouver la suite. Trois règles simples :</p> <ul> <li><strong>Des liens dans le texte</strong>, avec des mots qui décrivent la page de destination : « notre tarif de pose de climatisation » plutôt que « cliquez ici ».</li> <li><strong>Chaque article mène vers une page service</strong>, là où le lecteur peut vous contacter.</li> <li><strong>Aucune page orpheline</strong> : chaque page importante doit être accessible depuis le menu ou depuis une autre page.</li> </ul> <h2>Ce qu''il faut éviter</h2> <ul class="checklist"> <li><strong>Répéter le mot-clé à chaque phrase.</strong> Google le repère et le lecteur aussi. Écrivez naturellement.</li> <li><strong>Publier des textes produits en masse.</strong> Les règles anti-spam de Google visent les pages créées en grand nombre surtout pour se positionner, sans aider le lecteur, qu''elles soient écrites à la main ou par une IA.</li> <li><strong>Copier le texte d''un fournisseur ou d''un concurrent.</strong> Une page identique à une autre n''apporte rien de plus.</li> <li><strong>Laisser des pages vides ou dépassées</strong> : « page en construction », promotions terminées, anciens tarifs.</li> </ul> <div class="encadre-digita"> <p class="encadre-titre">Ce que fait DIGITA</p> <p>L''audit technique et l''optimisation des pages coûtent 590 €. L''offre complète, avec audit, optimisation et plan de contenus sur 3 mois, coûte 1 200 €. Le diagnostic gratuit permet de voir par quelles pages commencer.</p> <p><a href="/services#seo" class="encadre-lien">Voir l''offre SEO</a> · <a href="/diagnostic" class="encadre-lien">Réserver un diagnostic gratuit</a></p> </div> <h2>Questions fréquentes</h2> <h3>Combien de mots faut-il pour qu''une page soit bien classée ?</h3> <p>Il n''y a pas de nombre minimal. Une page doit être assez complète pour répondre à la question, ni plus ni moins. Une page service tient souvent en 400 à 800 mots, un guide en davantage.</p> <h3>Faut-il publier des articles toutes les semaines ?</h3> <p>Non. Mieux vaut un article utile par mois, tenu à jour, que des articles publiés pour publier. Commencez par vos pages services : ce sont elles qui amènent des demandes.</p> <h3>Peut-on écrire ses pages avec ChatGPT ?</h3> <p>Oui pour préparer un plan ou reformuler, à condition de relire, de corriger et d''ajouter ce que vous seul savez : vos prix, vos réalisations, votre façon de travailler. Google juge l''utilité du contenu, pas l''outil qui l''a écrit.</p> <div class="article-sources"> <p class="encadre-titre">Sources</p> <ul> <li><a href="https://developers.google.com/search/docs/fundamentals/seo-starter-guide?hl=fr" target="_blank" rel="noopener">Google Search Central : bien débuter en référencement naturel (SEO)</a>.</li> <li><a href="https://developers.google.com/search/docs/fundamentals/creating-helpful-content?hl=fr" target="_blank" rel="noopener">Google Search Central : créer du contenu utile, fiable et people-first</a>.</li> <li><a href="https://developers.google.com/search/docs/essentials/spam-policies?hl=fr#scaled-content" target="_blank" rel="noopener">Google Search Central : règles relatives au spam (contenu à grande échelle)</a>.</li> <li>Grille tarifaire DIGITA : <a href="/tarifs">page Tarifs</a>, consultée le 9 novembre 2026.</li> </ul> </div>', 'Écrire pour Google quand on est une TPE', 'Trouver les mots de vos clients, structurer une page, soigner le titre et les liens internes : la méthode simple pour qu''une TPE soit trouvée sur Google.', 'écrire pour Google, rédaction SEO TPE, référencement naturel petite entreprise, mots-clés locaux, balise title', '/assets/images/blog/ecrire-pour-google-tpe.webp', '/assets/images/blog/ecrire-pour-google-tpe.webp', 'draft', NOW(), NOW(), 'guide')
ON CONFLICT (slug) DO NOTHING;

INSERT INTO blog_articles (title, slug, category_id, service_name, excerpt, content, meta_title, meta_description, meta_keywords, featured_image, image_url, status, created_at, updated_at, content_type)
VALUES ('Entretenir et sécuriser son site : le minimum à faire', 'entretenir-securiser-site', (SELECT id FROM service_categories WHERE slug = 'creation-web'), 'Sites web et landing', 'Un site non entretenu devient lent, vulnérable, puis tombe en panne. Les quatre gestes essentiels, un calendrier simple et la fiche « qui gère quoi » à tenir à jour.', '<div class="en-bref"> <p class="en-bref-titre">En bref</p> <ul> <li>Un site n''est pas « fini » le jour de sa mise en ligne. Sans mises à jour ni sauvegardes, il devient lent, vulnérable, puis tombe en panne.</li> <li>Quatre gestes protègent l''essentiel : mettre à jour, sauvegarder (et tester la restauration), sécuriser les accès, garder le HTTPS actif.</li> <li>Notez qui gère quoi (hébergement, nom de domaine, accès) : c''est ce qui manque le plus le jour d''un problème.</li> </ul> </div> <p>Un matin, un client vous appelle : votre site affiche une page de pharmacie en ligne, ou un message « site dangereux ». Dans la plupart des cas, la cause est banale : une extension pas mise à jour depuis des mois, un mot de passe trop simple, ou un ancien prestataire qui avait encore la main.</p> <p>Cybermalveillance.gouv.fr, le dispositif national d''assistance, le rappelle dans sa fiche sur la sécurité des sites : les mises à jour corrigent des failles connues, et une sauvegarde régulière permet de repartir après un incident. Voici l''entretien minimal, à faire vous-même ou à confier à votre prestataire.</p> <h2>Ce qui peut arriver à un site mal entretenu</h2> <table class="table-article"> <thead><tr><th>Problème</th><th>Ce que voit le client</th><th>Cause fréquente</th></tr></thead> <tbody> <tr><td>Piratage (défiguration)</td><td>Pages modifiées, contenus étrangers, redirections</td><td>CMS ou extension pas à jour, mot de passe faible</td></tr> <tr><td>Alerte « site non sécurisé »</td><td>Avertissement du navigateur avant d''entrer</td><td>Certificat HTTPS expiré ou mal installé</td></tr> <tr><td>Site inaccessible</td><td>Page d''erreur ou page de l''hébergeur</td><td>Hébergement ou nom de domaine non renouvelé</td></tr> <tr><td>Formulaire muet</td><td>Rien, mais les demandes n''arrivent plus</td><td>Adresse de réception changée, e-mails classés en indésirables</td></tr> <tr><td>Site très lent</td><td>Pages qui mettent plusieurs secondes à s''afficher</td><td>Images trop lourdes, extensions inutiles, hébergement saturé</td></tr> </tbody> </table> <h2>Les 4 gestes d''entretien</h2> <ol class="etapes"> <li><strong>Mettre à jour.</strong> Le CMS (WordPress, par exemple), le thème et les extensions reçoivent des correctifs de sécurité. Appliquez-les régulièrement, et supprimez les extensions que vous n''utilisez plus : une extension désactivée mais présente peut rester une porte d''entrée.</li> <li><strong>Sauvegarder, puis tester.</strong> Une sauvegarde automatique, au moins chaque semaine, des fichiers et de la base de données, conservée ailleurs que sur le serveur du site. Une fois par an, vérifiez qu''on sait réellement la restaurer : une sauvegarde jamais testée ne protège de rien.</li> <li><strong>Sécuriser les accès.</strong> Un mot de passe long et unique par compte, la double authentification quand elle existe, un compte par personne, et la suppression des accès des anciens salariés et prestataires.</li> <li><strong>Garder le HTTPS actif.</strong> Le petit cadenas dans la barre d''adresse indique que les échanges sont chiffrés. Le certificat se renouvelle en général automatiquement chez l''hébergeur ; vérifiez-le si le navigateur affiche une alerte.</li> </ol> <h2>Le calendrier d''entretien</h2> <table class="table-article"> <thead><tr><th>Fréquence</th><th>À faire</th></tr></thead> <tbody> <tr><td>Chaque semaine</td><td>Vérifier que les sauvegardes automatiques ont tourné ; appliquer les mises à jour de sécurité</td></tr> <tr><td>Chaque mois</td><td>Envoyer une demande test par le formulaire ; vérifier que le site s''ouvre bien sur téléphone</td></tr> <tr><td>Chaque trimestre</td><td>Faire le tour des comptes ayant accès au site ; supprimer extensions et pages inutiles</td></tr> <tr><td>Chaque année</td><td>Tester une restauration ; vérifier les dates de renouvellement du nom de domaine et de l''hébergement</td></tr> </tbody> </table> <div class="encadre-exemple"> <p class="encadre-titre">Exemple (cas fictif) : un cabinet de kinésithérapie à Saint-André</p> <p>Le site avait été créé il y a quatre ans par un ami, qui ne s''en occupe plus. Le cabinet découvre que l''extension de réservation n''a pas été mise à jour depuis deux ans. Il retrouve les accès, fait faire une sauvegarde, met à jour le CMS et les extensions, supprime trois extensions inutiles et crée un accès personnel pour la secrétaire, avec la double authentification. Il note dans un document qui gère l''hébergement et le nom de domaine.</p> </div> <h2>La fiche « qui gère quoi »</h2> <p>Le jour d''un problème, la première perte de temps est de retrouver les accès. Gardez une fiche à jour, rangée dans un gestionnaire de mots de passe ou un coffre sécurisé :</p> <ul class="checklist"> <li><strong>Nom de domaine</strong> : chez quel registraire, au nom de qui, date de renouvellement. Voir notre article sur le <a href="/blog/nom-de-domaine-entreprise">nom de domaine</a>.</li> <li><strong>Hébergement</strong> : le fournisseur, l''offre, la date de renouvellement, le contact du support.</li> <li><strong>Administration du site</strong> : l''adresse de connexion et la liste des personnes qui ont un compte.</li> <li><strong>Messagerie</strong> : où sont gérées vos adresses e-mail professionnelles.</li> <li><strong>Prestataire</strong> : qui intervient, et ce qui est prévu au contrat (mises à jour, sauvegardes, délai d''intervention).</li> </ul> <h2>Si le site est piraté</h2> <p>Ne supprimez rien dans la précipitation. Prévenez votre hébergeur et votre prestataire, changez les mots de passe depuis un appareil sain, et restaurez une sauvegarde antérieure au piratage. Cybermalveillance.gouv.fr propose un parcours d''assistance en ligne et une liste de prestataires de proximité. Si des données de clients ont pu être consultées, la CNIL demande de notifier la violation dans les 72 heures.</p> <div class="encadre-digita"> <p class="encadre-titre">Ce que fait DIGITA</p> <p>Dans le pack Visibilité locale 974, le site vitrine est livré avec l''hébergement inclus, pour 990 €. Pour un site existant, le diagnostic gratuit permet de faire le point sur ses accès, ses sauvegardes et ses mises à jour.</p> <p><a href="/solutions#local" class="encadre-lien">Le pack Visibilité locale 974</a> · <a href="/diagnostic" class="encadre-lien">Réserver un diagnostic gratuit</a></p> </div> <h2>Questions fréquentes</h2> <h3>Mon hébergeur fait-il déjà les sauvegardes ?</h3> <p>Souvent oui, mais pas toujours, et pas forcément assez longtemps. Vérifiez dans votre offre la fréquence, la durée de conservation et la façon de restaurer. Une copie gardée ailleurs reste prudente.</p> <h3>Le HTTPS est-il obligatoire ?</h3> <p>Les navigateurs signalent les sites sans HTTPS comme « non sécurisés », ce qui fait fuir les visiteurs. Dès qu''un site a un formulaire, le HTTPS protège les données envoyées. La plupart des hébergeurs le fournissent gratuitement.</p> <h3>Faut-il un contrat de maintenance ?</h3> <p>Si personne dans l''entreprise n''a le temps de faire les mises à jour et de vérifier les sauvegardes, oui. Demandez ce qui est inclus précisément et en combien de temps le prestataire intervient en cas de panne.</p> <div class="article-sources"> <p class="encadre-titre">Sources</p> <ul> <li><a href="https://www.cybermalveillance.gouv.fr/medias/2021/04/210722_FichePratique_SitesInternet.pdf" target="_blank" rel="noopener">Cybermalveillance.gouv.fr : fiche pratique « Sécurité des sites internet »</a>.</li> <li><a href="https://www.cybermalveillance.gouv.fr/tous-nos-contenus/bonnes-pratiques/10-mesures-essentielles-assurer-securite-numerique" target="_blank" rel="noopener">Cybermalveillance.gouv.fr : les 10 mesures essentielles pour votre cybersécurité</a>.</li> <li><a href="https://www.cnil.fr/fr/notifier-une-violation-de-donnees-personnelles" target="_blank" rel="noopener">CNIL : notifier une violation de données personnelles</a>.</li> <li>Grille tarifaire DIGITA : <a href="/solutions#local">pack Visibilité locale 974</a>, consulté le 9 novembre 2026.</li> </ul> </div>', 'Entretenir et sécuriser son site : le minimum', 'Mises à jour, sauvegardes testées, accès sécurisés, HTTPS : les quatre gestes d''entretien d''un site de TPE, et que faire en cas de piratage.', 'sécuriser son site, maintenance site internet, sauvegarde site, mise à jour WordPress, site piraté', '/assets/images/blog/entretenir-securiser-site.webp', '/assets/images/blog/entretenir-securiser-site.webp', 'draft', NOW(), NOW(), 'guide')
ON CONFLICT (slug) DO NOTHING;

INSERT INTO blog_articles (title, slug, category_id, service_name, excerpt, content, meta_title, meta_description, meta_keywords, featured_image, image_url, status, created_at, updated_at, content_type)
VALUES ('Accélérer son site : mesurer puis corriger en 6 gestes', 'accelerer-son-site', (SELECT id FROM service_categories WHERE slug = 'creation-web'), 'Sites web et landing', 'Un site lent fait fuir les visiteurs sur mobile. Les trois mesures de Google, comment tester gratuitement avec PageSpeed Insights, et les six corrections les plus rentables.', '<div class="en-bref"> <p class="en-bref-titre">En bref</p> <ul> <li>Un site lent fait partir les visiteurs, surtout sur téléphone. Google mesure trois signaux de confort : l''affichage du contenu principal, la réactivité aux clics et la stabilité de la page.</li> <li>Mesurez d''abord avec PageSpeed Insights (gratuit), page par page, en regardant la version mobile.</li> <li>Dans la plupart des petits sites, les images trop lourdes sont la première cause de lenteur. Viennent ensuite les extensions et scripts inutiles.</li> </ul> </div> <p>Vous ouvrez votre site sur votre téléphone, en 4G, quelque part entre Cilaos et Saint-Louis. Trois secondes, quatre secondes, toujours une page blanche. Vos clients vivent la même chose, et beaucoup n''attendent pas : ils reviennent aux résultats de Google et cliquent sur le concurrent.</p> <p>Accélérer un site n''est pas réservé aux développeurs. Les gains les plus importants viennent souvent de gestes simples. Voici comment mesurer, puis corriger, dans l''ordre.</p> <h2>Les trois signaux de Google</h2> <p>Google regroupe la vitesse et le confort d''une page sous le nom de Core Web Vitals. Ce sont trois mesures, faites sur les visites réelles :</p> <table class="table-article"> <thead><tr><th>Mesure</th><th>Ce qu''elle mesure</th><th>Bon</th><th>Mauvais</th></tr></thead> <tbody> <tr><td>LCP (Largest Contentful Paint)</td><td>Le temps d''affichage du plus gros élément visible : la grande image ou le titre</td><td>2,5 s ou moins</td><td>Plus de 4 s</td></tr> <tr><td>INP (Interaction to Next Paint)</td><td>Le délai de réaction quand on touche un bouton ou un menu</td><td>200 ms ou moins</td><td>Plus de 500 ms</td></tr> <tr><td>CLS (Cumulative Layout Shift)</td><td>Les décalages de la page pendant le chargement (le bouton qui bouge au moment de cliquer)</td><td>0,1 ou moins</td><td>Plus de 0,25</td></tr> </tbody> </table> <p>Ces seuils sont ceux publiés par Google sur web.dev. Ils s''appliquent aux trois quarts des visites : une page est « bonne » quand au moins 75 visites sur 100 restent sous le seuil.</p> <h2>Mesurer en 3 étapes</h2> <ol class="etapes"> <li><strong>Ouvrez PageSpeed Insights</strong> (pagespeed.web.dev) et collez l''adresse de la page à tester : l''accueil, puis vos pages les plus importantes.</li> <li><strong>Regardez l''onglet « Mobile »</strong>. En haut, les données réelles des visiteurs, quand Google en a assez ; en dessous, un test en laboratoire avec une note sur 100 et la liste des problèmes.</li> <li><strong>Notez les trois premières recommandations</strong>, en particulier celles qui parlent d''images, de scripts et de polices. Ce sont souvent les plus rentables.</li> </ol> <p>Votre site est relié à la Search Console ? Le rapport « Core Web Vitals » liste les pages lentes à partir des visites réelles. Voir notre <a href="/blog/google-analytics-search-console">pas à pas Search Console</a>.</p> <h2>Corriger en 6 gestes</h2> <ol class="etapes"> <li><strong>Alléger les images.</strong> Une photo prise au téléphone pèse souvent plusieurs mégaoctets. Redimensionnez-la à la taille d''affichage (rarement plus de 2 000 pixels de large) et enregistrez-la en WebP ou en JPEG compressé. C''est souvent le geste qui fait gagner le plus.</li> <li><strong>Fixer la taille des images et des blocs.</strong> Une image avec sa largeur et sa hauteur déclarées réserve sa place, et la page ne saute plus pendant le chargement (meilleur CLS).</li> <li><strong>Charger les images plus bas « à la demande ».</strong> Les images situées sous l''écran peuvent attendre que le visiteur fasse défiler. La plupart des CMS le proposent ; ne l''appliquez pas à la grande image du haut.</li> <li><strong>Supprimer les extensions et scripts inutiles.</strong> Chaque module de chat, de statistiques ou de réseau social ajoute du code à charger. Gardez ceux qui servent vraiment.</li> <li><strong>Activer le cache et la compression.</strong> La plupart des hébergeurs le proposent, ou une extension dédiée. Les pages déjà visitées s''affichent alors beaucoup plus vite.</li> <li><strong>Limiter les polices.</strong> Deux familles de polices, avec peu de graisses, suffisent. Chaque variante est un fichier de plus à télécharger.</li> </ol> <div class="encadre-exemple"> <p class="encadre-titre">Exemple (cas fictif) : un traiteur à Sainte-Marie</p> <p>Sa page d''accueil affiche douze photos de plats, prises au téléphone et mises en ligne telles quelles. PageSpeed Insights indique un LCP très au-dessus de 4 secondes sur mobile. Il fait redimensionner et convertir les photos en WebP, déclare leur taille, charge à la demande celles du bas de page et retire un ancien module Instagram. Au test suivant, la grande image s''affiche nettement plus vite et la page ne saute plus.</p> </div> <h2>Quand faire appel à un professionnel</h2> <p>Si la note reste mauvaise après ces gestes, le problème vient souvent du thème, d''un constructeur de pages trop lourd ou de l''hébergement. Un audit technique permet de trouver la cause précise avant de dépenser dans un nouvel hébergement ou une refonte.</p> <ul class="checklist"> <li>Le serveur met longtemps à répondre, même sur une page simple.</li> <li>Le thème charge des dizaines de fichiers, y compris ceux que vous n''utilisez pas.</li> <li>Le site plante ou ralentit fortement quand plusieurs personnes le consultent.</li> </ul> <div class="encadre-digita"> <p class="encadre-titre">Ce que fait DIGITA</p> <p>L''audit technique et l''optimisation des pages coûtent 590 €. Le diagnostic gratuit permet de savoir si votre site a besoin d''un nettoyage ou d''une refonte.</p> <p><a href="/services#seo" class="encadre-lien">Voir l''offre SEO</a> · <a href="/diagnostic" class="encadre-lien">Réserver un diagnostic gratuit</a></p> </div> <h2>Questions fréquentes</h2> <h3>La vitesse joue-t-elle sur le classement Google ?</h3> <p>Elle fait partie de l''expérience de page que Google prend en compte, mais le contenu reste le premier critère. Un site rapide et vide ne passera pas devant une page lente qui répond mieux. La vitesse compte surtout pour ne pas perdre les visiteurs.</p> <h3>Ma note PageSpeed est de 60 sur 100, est-ce grave ?</h3> <p>Pas forcément. La note de laboratoire varie d''un test à l''autre. Regardez surtout les trois mesures LCP, INP et CLS des visites réelles, et corrigez ce qui est indiqué comme mauvais.</p> <h3>Faut-il changer d''hébergeur pour aller plus vite ?</h3> <p>Seulement si le serveur est vraiment en cause. Allégez d''abord les images et les extensions : c''est gratuit et souvent suffisant.</p> <div class="article-sources"> <p class="encadre-titre">Sources</p> <ul> <li><a href="https://web.dev/articles/vitals?hl=fr" target="_blank" rel="noopener">web.dev (Google) : les Core Web Vitals</a>.</li> <li><a href="https://web.dev/articles/defining-core-web-vitals-thresholds?hl=fr" target="_blank" rel="noopener">web.dev (Google) : comment les seuils des Core Web Vitals ont été définis</a>.</li> <li><a href="https://support.google.com/webmasters/answer/9205520?hl=fr" target="_blank" rel="noopener">Aide Search Console : rapport Core Web Vitals</a>.</li> <li><a href="https://pagespeed.web.dev/" target="_blank" rel="noopener">PageSpeed Insights</a>.</li> <li>Grille tarifaire DIGITA : <a href="/tarifs">page Tarifs</a>, consultée le 9 novembre 2026.</li> </ul> </div>', 'Accélérer son site : mesurer puis corriger', 'LCP, INP, CLS : comprendre les Core Web Vitals, mesurer avec PageSpeed Insights, puis corriger en 6 gestes simples (images, scripts, cache, polices).', 'accélérer son site, vitesse site internet, Core Web Vitals, PageSpeed Insights, optimiser images WebP', '/assets/images/blog/accelerer-son-site.webp', '/assets/images/blog/accelerer-son-site.webp', 'draft', NOW(), NOW(), 'pas-a-pas')
ON CONFLICT (slug) DO NOTHING;

INSERT INTO blog_articles (title, slug, category_id, service_name, excerpt, content, meta_title, meta_description, meta_keywords, featured_image, image_url, status, created_at, updated_at, content_type)
VALUES ('Search Console et Google Analytics : installer et suivre l''essentiel', 'google-analytics-search-console', (SELECT id FROM service_categories WHERE slug = 'seo'), 'SEO', 'Deux outils gratuits de Google pour savoir si votre site sert à quelque chose. Installation pas à pas, rapports à suivre chaque mois et règles de consentement.', '<div class="en-bref"> <p class="en-bref-titre">En bref</p> <ul> <li>La Search Console dit comment Google voit votre site : les recherches qui l''affichent, les clics, les pages indexées et les erreurs. Elle est gratuite et ne pose aucun cookie chez vos visiteurs.</li> <li>Google Analytics dit ce que font les visiteurs une fois sur le site : d''où ils viennent, quelles pages ils lisent, s''ils vous contactent.</li> <li>Google Analytics dépose des cookies : selon la CNIL, il faut recueillir le consentement des visiteurs avant de l''activer.</li> </ul> </div> <p>« Est-ce que mon site sert à quelque chose ? » Sans outil de mesure, impossible de répondre. Vous ne savez pas si des clients vous trouvent sur Google, avec quels mots, ni s''ils vont jusqu''au formulaire de contact.</p> <p>Deux outils gratuits de Google répondent à ces questions. Ils ne font pas la même chose, et se complètent. Voici comment les installer et quoi regarder, sans se noyer dans les chiffres.</p> <h2>Deux outils, deux rôles</h2> <table class="table-article"> <thead><tr><th></th><th>Search Console</th><th>Google Analytics 4</th></tr></thead> <tbody> <tr><td>Question posée</td><td>Comment Google voit-il mon site ?</td><td>Que font les visiteurs sur mon site ?</td></tr> <tr><td>Ce qu''on y lit</td><td>Recherches, impressions, clics, position moyenne, pages indexées, erreurs</td><td>Visites, sources de trafic, pages vues, actions (formulaire, appel)</td></tr> <tr><td>Installation</td><td>Validation de la propriété du site, une seule fois</td><td>Une balise ajoutée sur toutes les pages</td></tr> <tr><td>Cookies chez le visiteur</td><td>Aucun</td><td>Oui : consentement à recueillir</td></tr> </tbody> </table> <h2>Installer la Search Console en 5 étapes</h2> <ol class="etapes"> <li><strong>Connectez-vous</strong> sur search.google.com/search-console avec le compte Google de l''entreprise (pas un compte personnel que vous pourriez perdre).</li> <li><strong>Ajoutez une propriété.</strong> Choisissez « Domaine » si vous pouvez modifier la zone DNS de votre nom de domaine : elle couvre toutes les adresses du site. Sinon, choisissez « Préfixe d''URL » et saisissez l''adresse exacte, avec https.</li> <li><strong>Validez la propriété.</strong> Pour un domaine, copiez l''enregistrement TXT fourni par Google dans la zone DNS, chez votre registraire. Pour un préfixe d''URL, plusieurs méthodes existent : balise meta, fichier HTML, ou validation par Google Analytics si la balise est déjà installée.</li> <li><strong>Envoyez votre sitemap.</strong> Dans le menu « Sitemaps », indiquez l''adresse du plan du site, souvent votre-site.re/sitemap.xml. Google découvre ainsi toutes vos pages.</li> <li><strong>Ajoutez votre prestataire comme utilisateur</strong>, avec un accès limité si possible, plutôt que de partager votre mot de passe.</li> </ol> <h2>Ce qu''il faut regarder chaque mois</h2> <ul class="checklist"> <li><strong>Rapport « Performances »</strong> : les recherches qui ont affiché votre site, avec les impressions, les clics et la position moyenne. Repérez les recherches qui ont beaucoup d''impressions et peu de clics : un titre de page plus clair peut changer la donne.</li> <li><strong>Pages qui ramènent des clics</strong> : ce sont celles à soigner en priorité (mise à jour, appel à l''action visible).</li> <li><strong>Rapport « Pages » (indexation)</strong> : les pages que Google n''indexe pas, et pourquoi. Une page importante absente de l''index mérite une vérification.</li> <li><strong>Rapport « Core Web Vitals »</strong> : les pages jugées lentes sur mobile. Voir <a href="/blog/accelerer-son-site">accélérer son site</a>.</li> </ul> <h2>Installer Google Analytics 4</h2> <ol class="etapes"> <li><strong>Créez un compte et une propriété</strong> sur analytics.google.com, avec le fuseau horaire de La Réunion et l''euro comme devise.</li> <li><strong>Ajoutez un flux de données « Web »</strong> avec l''adresse de votre site. Google vous donne un identifiant de mesure qui commence par « G- ».</li> <li><strong>Installez la balise</strong> sur toutes les pages : par l''extension de votre CMS, par Google Tag Manager, ou par votre prestataire.</li> <li><strong>Branchez-la sur votre bandeau cookies.</strong> La balise ne doit déposer ses cookies qu''après l''accord du visiteur. Refuser doit être aussi simple qu''accepter.</li> <li><strong>Déclarez vos actions importantes</strong> comme événements clés : envoi du formulaire, clic sur le téléphone, réservation. Ce sont elles qui mesurent l''utilité du site.</li> </ol> <div class="encadre-exemple"> <p class="encadre-titre">Exemple (cas fictif) : un moniteur de parapente à Saint-Leu</p> <p>Dans la Search Console, il découvre que sa page tarifs apparaît souvent pour « baptême parapente Saint-Leu prix », mais reçoit peu de clics. Il réécrit le titre de la page pour qu''il annonce le prix et la durée du vol. Dans Analytics, il déclare le clic sur le bouton « Réserver » comme événement clé, pour voir quelles pages mènent vraiment à une réservation.</p> </div> <h2>Cookies et consentement</h2> <p>La CNIL dispense de consentement certains outils de mesure d''audience, à des conditions strictes : usage limité à des statistiques pour le seul compte du site, données non croisées ni réutilisées par le fournisseur. Elle cite Google Analytics parmi les offres qui sortent de cette exemption, parce que le fournisseur indique réutiliser les données pour son propre compte. Il faut donc le déclencher seulement après l''accord du visiteur, ce qui réduit le nombre de visites mesurées.</p> <p>La Search Console, elle, ne dépose rien chez vos visiteurs : vous pouvez l''installer sans bandeau.</p> <div class="encadre-digita"> <p class="encadre-titre">Ce que fait DIGITA</p> <p>L''audit technique et l''optimisation des pages coûtent 590 €. Le diagnostic gratuit permet de vérifier ce qui est déjà installé sur votre site.</p> <p><a href="/services#seo" class="encadre-lien">Voir l''offre SEO</a> · <a href="/diagnostic" class="encadre-lien">Réserver un diagnostic gratuit</a></p> </div> <h2>Questions fréquentes</h2> <h3>La Search Console améliore-t-elle mon classement ?</h3> <p>Non, l''installer ne change pas votre position. Elle vous montre ce qui se passe et ce qui bloque, pour que vous puissiez corriger.</p> <h3>Faut-il Google Analytics si j''ai la Search Console ?</h3> <p>Pour un petit site, la Search Console suffit souvent au début. Analytics devient utile quand vous voulez savoir quelles pages mènent à une demande de devis ou à une réservation.</p> <h3>Pourquoi Analytics affiche moins de visites que prévu ?</h3> <p>Parce que les visiteurs qui refusent les cookies ne sont pas mesurés, et que certains bloqueurs empêchent la balise de se charger. Comparez les tendances d''un mois sur l''autre plutôt que les chiffres bruts.</p> <div class="article-sources"> <p class="encadre-titre">Sources</p> <ul> <li><a href="https://support.google.com/webmasters/answer/34592?hl=fr" target="_blank" rel="noopener">Aide Search Console : ajouter une propriété de site Web</a>.</li> <li><a href="https://support.google.com/webmasters/answer/10267942?hl=fr" target="_blank" rel="noopener">Aide Search Console : premiers pas avec la Search Console</a>.</li> <li><a href="https://support.google.com/analytics/answer/9304153?hl=fr" target="_blank" rel="noopener">Aide Google Analytics : configurer Analytics pour un site Web</a>.</li> <li><a href="https://www.cnil.fr/fr/mesurer-la-frequentation-de-vos-sites-web-et-de-vos-applications" target="_blank" rel="noopener">CNIL : mesurer la fréquentation de vos sites web et de vos applications</a>.</li> <li><a href="https://www.cnil.fr/fr/cookies-et-autres-traceurs/regles/cookies-solutions-pour-les-outils-de-mesure-daudience" target="_blank" rel="noopener">CNIL : cookies, solutions pour les outils de mesure d''audience</a>.</li> <li>Grille tarifaire DIGITA : <a href="/tarifs">page Tarifs</a>, consultée le 9 novembre 2026.</li> </ul> </div>', 'Search Console et Google Analytics : le pas à pas', 'Installer la Search Console et Google Analytics 4, savoir quoi regarder chaque mois et respecter les règles de la CNIL sur les cookies.', 'Search Console, Google Analytics 4, installer GA4, mesure d''audience CNIL, statistiques site internet', '/assets/images/blog/google-analytics-search-console.webp', '/assets/images/blog/google-analytics-search-console.webp', 'draft', NOW(), NOW(), 'pas-a-pas')
ON CONFLICT (slug) DO NOTHING;

INSERT INTO blog_articles (title, slug, category_id, service_name, excerpt, content, meta_title, meta_description, meta_keywords, featured_image, image_url, status, created_at, updated_at, content_type)
VALUES ('Google Ads pour une TPE : lancer une première campagne sans gaspiller', 'google-ads-tpe', (SELECT id FROM service_categories WHERE slug = 'publicite-en-ligne'), 'Publicité', 'Une annonce qui s''affiche au moment où le client cherche. Le fonctionnement de Google Ads, une première campagne en six étapes et les pièges qui coûtent cher.', '<div class="en-bref"> <p class="en-bref-titre">En bref</p> <ul> <li>Google Ads affiche votre annonce quand quelqu''un cherche ce que vous vendez. Vous ne payez que les clics, au prix fixé par une enchère.</li> <li>Pour une TPE, une seule campagne bien ciblée suffit pour commencer : quelques mots-clés précis, une zone limitée, une page d''arrivée claire.</li> <li>Fixez un budget quotidien que vous pouvez perdre pendant un mois de test, et mesurez les demandes reçues, pas seulement les clics.</li> </ul> </div> <p>Votre fiche Google et votre site sont en place, mais il faut du temps pour remonter dans les résultats naturels. Pendant ce temps, vos concurrents apparaissent tout en haut, avec la mention « Sponsorisé ». C''est Google Ads : une publicité qui s''affiche au moment précis où le client cherche.</p> <p>Bien réglée, c''est l''une des publicités les plus efficaces pour une petite entreprise. Mal réglée, elle peut consommer un budget en quelques jours sans un seul appel. Voici les bases pour démarrer sans gaspiller.</p> <h2>Comment fonctionne Google Ads</h2> <ul> <li><strong>Des mots-clés</strong> : vous choisissez les recherches pour lesquelles votre annonce peut s''afficher (« dépannage climatisation Saint-Denis »).</li> <li><strong>Une enchère</strong> : à chaque recherche, Google choisit les annonces à afficher selon l''enchère et la qualité de l''annonce et de la page d''arrivée. Une annonce pertinente peut passer devant une enchère plus élevée.</li> <li><strong>Un paiement au clic</strong> : l''affichage est gratuit, vous payez quand quelqu''un clique.</li> <li><strong>Un budget quotidien moyen</strong> : Google peut dépenser jusqu''à deux fois ce montant un jour donné, mais pas plus de 30,4 fois sur le mois, selon son aide en ligne.</li> </ul> <h2>Google Ads ou publicité Facebook ?</h2> <table class="table-article"> <thead><tr><th></th><th>Google Ads (Réseau de Recherche)</th><th>Facebook et Instagram</th></tr></thead> <tbody> <tr><td>Le client</td><td>Cherche déjà une solution</td><td>Ne cherche rien, il fait défiler son fil</td></tr> <tr><td>Idéal pour</td><td>Dépannage, services urgents, demandes de devis</td><td>Faire connaître une offre, un événement, un produit visuel</td></tr> <tr><td>Format</td><td>Texte, à côté des résultats de recherche</td><td>Image ou vidéo</td></tr> <tr><td>À lire aussi</td><td>Cet article</td><td><a href="/blog/budget-publicite-facebook-reunion">Budget publicité Facebook à La Réunion</a></td></tr> </tbody> </table> <h2>Lancer une première campagne en 6 étapes</h2> <ol class="etapes"> <li><strong>Choisissez un objectif mesurable</strong> : appels, demandes de devis ou réservations. Pas « de la visibilité ».</li> <li><strong>Créez une campagne « Réseau de Recherche »</strong> et désactivez le Réseau Display et les partenaires de recherche au départ : vous gardez le contrôle de l''endroit où l''annonce s''affiche.</li> <li><strong>Limitez la zone</strong> aux communes que vous desservez, et choisissez les personnes qui se trouvent dans la zone plutôt que celles qui s''y intéressent.</li> <li><strong>Choisissez 10 à 20 mots-clés précis</strong>, en expression exacte ou en expression, qui montrent une intention d''achat (« prix », « devis », « dépannage », le nom de la commune). Ajoutez des mots-clés à exclure : « gratuit », « emploi », « formation ».</li> <li><strong>Écrivez une annonce qui répond à la recherche</strong> : le service, la zone, ce qui vous distingue (délai, devis gratuit), et le numéro de téléphone en extension d''appel.</li> <li><strong>Envoyez vers une page dédiée</strong>, pas vers l''accueil : une page qui parle exactement du service annoncé, avec un formulaire court et un bouton d''appel. Voir notre article sur la <a href="/blog/landing-page-definition">landing page</a>.</li> </ol> <div class="encadre-exemple"> <p class="encadre-titre">Exemple (cas fictif) : un dépanneur en électricité à Saint-Pierre</p> <p>Il lance une campagne limitée au Sud de l''île, avec des mots-clés comme « électricien urgence Saint-Pierre » et « panne électrique Le Tampon », et exclut « formation électricien ». L''annonce affiche son numéro et « Intervention sous 24 h ». Après un mois, il compare les appels reçus via l''annonce au budget dépensé, coupe les mots-clés qui n''ont rien donné et garde les trois qui ont amené des chantiers.</p> </div> <h2>Les pièges les plus coûteux</h2> <ul class="checklist"> <li><strong>Des mots-clés trop larges</strong> (« électricité ») qui affichent l''annonce pour des recherches sans rapport.</li> <li><strong>Aucun suivi des conversions</strong> : sans mesure des appels et des formulaires, impossible de savoir si une campagne rapporte.</li> <li><strong>Accepter toutes les recommandations automatiques</strong> sans les lire : certaines augmentent surtout le budget.</li> <li><strong>Une page d''arrivée lente ou confuse</strong> : vous payez le clic, puis le visiteur repart. Voir <a href="/blog/accelerer-son-site">accélérer son site</a>.</li> <li><strong>Juger trop tôt</strong> : laissez tourner au moins quelques semaines avant de conclure, puis ajustez.</li> </ul> <div class="encadre-digita"> <p class="encadre-titre">Ce que fait DIGITA</p> <p>Le pilotage de campagnes coûte 290 € par mois pour une plateforme (Google ou Meta), 490 € par mois pour deux plateformes avec tests A/B, et 790 € par mois en multi-plateformes avec retargeting et reporting hebdomadaire. Le budget publicitaire payé à Google s''ajoute.</p> <p><a href="/services#publicite" class="encadre-lien">Voir l''offre Publicité</a> · <a href="/diagnostic" class="encadre-lien">Réserver un diagnostic gratuit</a></p> </div> <h2>Questions fréquentes</h2> <h3>Quel budget prévoir pour commencer ?</h3> <p>Il dépend du prix des clics dans votre métier et de la concurrence locale. L''outil de planification des mots-clés de Google donne une estimation. Commencez par un budget que vous acceptez de consacrer à un mois de test, puis ajustez selon les demandes reçues.</p> <h3>Faut-il passer par une agence ?</h3> <p>Pas obligatoirement. Une petite campagne bien ciblée se gère seul, à condition d''y passer un peu de temps chaque semaine. Une agence fait gagner du temps et évite les réglages coûteux.</p> <h3>Google Ads aide-t-il mon référencement naturel ?</h3> <p>Non. Les annonces payantes et les résultats naturels sont séparés. Les deux se complètent : la publicité donne des résultats immédiats, le référencement travaille sur la durée.</p> <div class="article-sources"> <p class="encadre-titre">Sources</p> <ul> <li><a href="https://support.google.com/google-ads/answer/2375423?hl=fr" target="_blank" rel="noopener">Aide Google Ads : pourquoi les coûts quotidiens peuvent dépasser votre budget quotidien moyen</a>.</li> <li><a href="https://support.google.com/google-ads/answer/1704424?hl=fr" target="_blank" rel="noopener">Aide Google Ads : gérer vos dépenses</a>.</li> <li><a href="https://support.google.com/google-ads/answer/7478529?hl=fr" target="_blank" rel="noopener">Aide Google Ads : à propos des options de correspondance des mots clés</a>.</li> <li>Grille tarifaire DIGITA : <a href="/tarifs">page Tarifs</a>, consultée le 9 novembre 2026.</li> </ul> </div>', 'Google Ads pour une TPE : la première campagne', 'Mots-clés, enchères, budget quotidien, zone ciblée : comment fonctionne Google Ads et comment lancer une première campagne quand on est une TPE.', 'Google Ads TPE, publicité Google, campagne Réseau de Recherche, budget Google Ads, mots-clés à exclure', '/assets/images/blog/google-ads-tpe.webp', '/assets/images/blog/google-ads-tpe.webp', 'draft', NOW(), NOW(), 'guide')
ON CONFLICT (slug) DO NOTHING;

INSERT INTO blog_articles (title, slug, category_id, service_name, excerpt, content, meta_title, meta_description, meta_keywords, featured_image, image_url, status, created_at, updated_at, content_type)
VALUES ('Plan marketing digital sur une page : le modèle à remplir', 'plan-marketing-digital-une-page', (SELECT id FROM service_categories WHERE slug = 'publicite-en-ligne'), 'Stratégie digitale', 'Fini la dispersion entre réseaux, annuaires et idées du moment. Un modèle en sept cases, cinq étapes pour le remplir et les indicateurs qui comptent vraiment.', '<div class="en-bref"> <p class="en-bref-titre">En bref</p> <ul> <li>Un plan marketing digital tient sur une page : un objectif chiffré, un client type, trois canaux au maximum, un budget, un calendrier et deux ou trois indicateurs.</li> <li>Commencez par ce qui amène déjà des clients, et ajoutez un seul nouveau canal à la fois.</li> <li>Relisez le plan une fois par mois : gardez ce qui marche, arrêtez ce qui ne donne rien après trois mois.</li> </ul> </div> <p>Un mois, vous publiez tous les jours sur Facebook. Le suivant, rien. Puis un ami vous parle de TikTok, un commercial vous vend une publicité dans un annuaire, et vous refaites votre logo. À la fin de l''année, difficile de dire ce qui a vraiment rapporté.</p> <p>Un plan sur une page évite cette dispersion. Il ne demande ni logiciel ni consultant : une feuille, une heure, et des réponses honnêtes. Voici le modèle, à remplir puis à afficher près de votre bureau.</p> <h2>Le modèle en 7 cases</h2> <table class="table-article"> <thead><tr><th>Case</th><th>La question</th><th>Exemple de réponse</th></tr></thead> <tbody> <tr><td>1. Objectif</td><td>Que voulez-vous obtenir dans 6 mois, en chiffres ?</td><td>8 demandes de devis par mois au lieu de 3</td></tr> <tr><td>2. Client type</td><td>Qui achète, où, avec quel problème ?</td><td>Propriétaires de maison dans le Sud, qui rénovent une salle de bain</td></tr> <tr><td>3. Message</td><td>Pourquoi vous plutôt qu''un autre, en une phrase ?</td><td>« Devis sous 48 h et chantier propre, photos à l''appui »</td></tr> <tr><td>4. Canaux</td><td>Où votre client vous cherche-t-il ? Trois au maximum</td><td>Fiche Google, site (page service), Facebook</td></tr> <tr><td>5. Actions</td><td>Que faites-vous, et à quel rythme ?</td><td>2 publications par semaine, demander un avis après chaque chantier</td></tr> <tr><td>6. Budget</td><td>Combien en argent et en temps chaque mois ?</td><td>2 heures par semaine, plus un budget publicité fixe</td></tr> <tr><td>7. Indicateurs</td><td>Comment saurez-vous que ça marche ?</td><td>Demandes reçues, appels depuis la fiche Google, avis</td></tr> </tbody> </table> <div class="encadre-exemple"> <p class="encadre-titre">Modèle à adapter</p> <p>Objectif à 6 mois : … · Client type : … · Notre promesse : … · Canal 1 : … (action et rythme) · Canal 2 : … · Canal 3 : … · Temps par semaine : … · Budget par mois : … · Indicateurs suivis : … · Date de la prochaine revue : …</p> </div> <h2>Remplir le plan en 5 étapes</h2> <ol class="etapes"> <li><strong>Partez de vos clients actuels.</strong> Demandez-vous comment les trois derniers vous ont trouvé : bouche-à-oreille, Google, Facebook, passage devant la boutique. Les canaux qui marchent déjà sont vos premiers à renforcer.</li> <li><strong>Fixez un seul objectif principal.</strong> Plus de demandes de devis, plus de réservations, ou un panier moyen plus élevé. Un objectif chiffré et daté, pas « être plus visible ».</li> <li><strong>Choisissez trois canaux au maximum.</strong> Pour un commerce de proximité, la <a href="/blog/fiche-google-reunion">fiche Google</a> est presque toujours le premier. Ajoutez un réseau social là où sont vos clients (voir <a href="/blog/instagram-ou-facebook-reunion">Instagram ou Facebook</a>), et votre site ou une page dédiée.</li> <li><strong>Traduisez chaque canal en actions régulières.</strong> Une action que vous tiendrez vaut mieux qu''un programme ambitieux abandonné en mars. Bloquez les créneaux dans votre agenda.</li> <li><strong>Prévoyez la revue mensuelle.</strong> Une demi-heure en début de mois : les indicateurs, ce qui a marché, ce qui change pour le mois suivant.</li> </ol> <h2>Les indicateurs à suivre</h2> <ul class="checklist"> <li><strong>Le nombre de demandes</strong> (appels, formulaires, messages) : c''est l''indicateur principal.</li> <li><strong>D''où viennent ces demandes</strong> : demandez-le à chaque nouveau client, et notez-le dans un tableau.</li> <li><strong>Les actions de la fiche Google</strong> : appels, itinéraires, visites du site, visibles dans votre fiche.</li> <li><strong>Les avis reçus</strong> : leur nombre et leur note moyenne. Voir notre guide sur les <a href="/blog/avis-google-entreprise">avis Google</a>.</li> </ul> <p>Le nombre d''abonnés ou de « j''aime » peut rassurer, mais il ne paie pas les factures. Gardez-le comme indicateur secondaire.</p> <div class="encadre-exemple"> <p class="encadre-titre">Exemple (cas fictif) : un institut de beauté à Saint-Benoît</p> <p>La gérante publiait au hasard sur trois réseaux. Elle remplit le plan : objectif de 20 rendez-vous en ligne par mois, clientes de 25 à 50 ans de l''Est, promesse « soins naturels et créneaux le samedi ». Elle garde la fiche Google, Instagram et la réservation en ligne, abandonne TikTok, et fait le point chaque premier lundi du mois.</p> </div> <div class="encadre-digita"> <p class="encadre-titre">Ce que fait DIGITA</p> <p>Le diagnostic gratuit de 30 minutes permet de remplir ce plan avec vous : ce qui marche déjà, les canaux à garder et ceux à laisser de côté. Si un chantier ressort, le prix vient de la grille tarifaire, par exemple 390 € pour optimiser votre fiche Google et vos avis.</p> <p><a href="/diagnostic" class="encadre-lien">Réserver un diagnostic gratuit</a> · <a href="/tarifs" class="encadre-lien">Voir les tarifs</a></p> </div> <h2>Questions fréquentes</h2> <h3>Faut-il être présent sur tous les réseaux sociaux ?</h3> <p>Non. Mieux vaut un réseau bien tenu que quatre abandonnés. Choisissez celui où se trouvent vos clients et où vous pouvez publier régulièrement.</p> <h3>Quel budget consacrer au marketing digital ?</h3> <p>Il n''y a pas de règle valable pour tous. Partez de ce que vous pouvez tenir dans la durée, en argent et en temps, et augmentez seulement ce qui a fait ses preuves.</p> <h3>Combien de temps avant de voir des résultats ?</h3> <p>La publicité donne des résultats en quelques jours, la fiche Google et les réseaux en quelques semaines, le référencement naturel en plusieurs mois. Jugez chaque canal sur au moins trois mois.</p> <div class="article-sources"> <p class="encadre-titre">Pour aller plus loin</p> <ul> <li><a href="/blog/bilan-digital-fin-annee">Bilan digital de fin d''année : la checklist en 20 points</a>.</li> <li><a href="/blog/idees-publications-reseaux-sociaux">30 idées de publications pour les réseaux sociaux</a>.</li> <li><a href="/blog/ecrire-pour-google-tpe">Écrire pour Google quand on est une TPE</a>.</li> <li>Grille tarifaire DIGITA : <a href="/tarifs">page Tarifs</a>, consultée le 9 novembre 2026.</li> </ul> </div>', 'Plan marketing digital sur une page : le modèle', 'Objectif chiffré, client type, trois canaux, budget, indicateurs : le modèle de plan marketing digital sur une page, à revoir chaque mois.', 'plan marketing digital, modèle plan marketing TPE, stratégie digitale petite entreprise, indicateurs marketing', '/assets/images/blog/plan-marketing-digital-une-page.webp', '/assets/images/blog/plan-marketing-digital-une-page.webp', 'draft', NOW(), NOW(), 'modele')
ON CONFLICT (slug) DO NOTHING;
